 static std::string Slot(const Key&k){return k.kind==Kind::Expression?"expression-group":Identity(k);}
 void IndexRuns(){runs.clear();for(auto&c:segments)for(auto&m:c.morphs)runs[Slot(m.key)].push_back({c.start,c.end});for(auto&[_,spans]:runs){std::sort(spans.begin(),spans.end());size_t n=0;for(auto span:spans){if(n&&span.first<=spans[n-1].second+1e-9)spans[n-1].second=std::max(spans[n-1].second,span.second);else spans[n++]=span;}spans.resize(n);}}
 double RunStart(const Key&key,double time,double fallback)const{auto found=runs.find(Slot(key));if(found==runs.end())return fallback;auto&spans=found->second;auto it=std::upper_bound(spans.begin(),spans.end(),time,[](double t,auto&s){return t<s.first;});return it==spans.begin()?fallback:(--it)->first;}

